@router.get("/ecommerce/carts/{cart_pk}")
async def get_shopping_cart(
    cart_pk: str,
    current_user: User = Depends(get_current_user)
):
    try:
        cart = CartOrderDraft.get(cart_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Cart draft not found")

    if cart.customer_id != str(current_user.id):
        raise HTTPException(status_code=403, detail="Forbidden: access to cart denied")

    return {
        "cart_id": cart.pk,
        "items": cart.items,
        "saved_shipping_address": cart.shipping_address,
        "payment_token": cart.tokenized_card_ref
    }
